import { Component, OnInit } from '@angular/core';
import { FormBuilder } from '@angular/forms';
import { Router } from '@angular/router';
import { Product } from 'src/app/model/Product';
import { AuthService } from 'src/app/services/auth.service';
import { ProductService } from 'src/app/services/product.service';

@Component({
  selector: 'app-home',
  templateUrl: './home.component.html',
  styleUrls: ['./home.component.scss']
})
export class HomeComponent implements OnInit{


  products: Product[] = [];
  allProducts: Product[] = [];
  cart: Product[] = [];

  constructor(
    private fb: FormBuilder,
    private router: Router,
    private authService: AuthService,
    private ProductService: ProductService,
    private arttService: CartService
  ) {}

  ngOnInit(): void {
    this.loadProducts();
  }

  loadProducts(): void {
    this.ProductService.listAllProducts().subscribe((response: any[]) => {
      console.log('API response:', response);
      const products = response.map(p => ({
        id: p.productId,
        title: p.title,
        description: p.description,
        quantity: p.availableQuantity,
        price: p.price,
        category: p.category,
        categoryId: p.categoryId
      }));
      this.products = products;
      this.allProducts = products;
    });
  }

  // onSearch removed: search is now handled by onFiltersChanged

  onFiltersChanged(filters: any): void {
    // If only search is used
    if (filters.searchText && !filters.selectedCategory && !filters.maxPrice && !filters.sortBy) {
      this.ProductService.searchProducts(filters.searchText).subscribe((response: any[]) => {
        const products = response.map(p => ({
          id: p.productId,
          title: p.title,
          description: p.description,
          quantity: p.availableQuantity,
          price: p.price,
          category: p.category,
          categoryId: p.categoryId
        }));
        this.products = products;
      });
      return;
    }

    // If any filter/sort is used
    const categoryId = filters.selectedCategory ? filters.selectedCategory : '';
    const minPrice = 0;
    const maxPrice = filters.maxPrice !== undefined && filters.maxPrice !== null ? filters.maxPrice : 5000;
    const sortBy = filters.sortBy ? filters.sortBy : '';

    this.ProductService.filterProducts(categoryId, minPrice, maxPrice, sortBy).subscribe((response: any[]) => {
      const products = response.map(p => ({
        id: p.productId,
        title: p.title,
        description: p.description,
        quantity: p.availableQuantity,
        price: p.price,
        category: p.category,
        categoryId: p.categoryId
      }));
      this.products = products;
    });
  }
  // addToCart(product: Product) {
  //   this.cart.push(product);
  //   alert(product.title + ' added to cart!');
  // }
  addToCart(product: Product) {
  this.CartService.addToCart(product.id, 1).subscribe({
    next: () => alert(product.title + ' added to cart!'),
    error: (err: { message: string; }) => alert('Failed to add to cart: ' + err.message)
  });
}

  viewDetailsEvent(productID: Number) {
    console.log('Navigating to product detail with ID:', productID);
    if (productID !== undefined && productID !== null) {
  this.router.navigate(['/customer/product-detail', productID]);
    } else {
      alert('Product ID is missing!');
    }
  }
}
